page.script:
// 触发事件
function CrrHandler(t) {
	// 确定事件
	if (t.id == "erpMaterieVerify") {
		var records = Ext.getCmp("erpMaterie").getSelectionModel().getSelection();
		if (records.length != 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行确认!");
			return false;
		}
		eval(t.callback + "(records[0].data)");
		erpMaterielWin.close();
	}
}
